//! OCaml: the ctypes bindings (`target/codegen/ocaml/`, facade module
//! `Azul`, generated by `doc/src/codegen/v2/lang_ocaml`).
//!
//! The idiomatic modules mix owned `{raw; disposed}` records with raw
//! structures, so the generated code uses the raw `foreign` layer (after
//! `open Azul`), which keeps the C name with a lowered first letter
//! (`azCssProperty_textColor`, variant constructors `azLayoutWidth_px`),
//! takes C-like enums as `int` (`LayoutDisplay.to_int LayoutDisplay.Flex`)
//! and ctypes structures (`az_color_u`, fields `az_color_u_field_r`, u8 as
//! `Unsigned.UInt8.t`). Structures are filled by the generated `az_struct`;
//! a `CssPropertyValue<T>` alias (an opaque blob) by `az_union` (the u8 tag,
//! then the payload at its own alignment); a Vec from a `CArray`.
//! A hand-built `CssProperty` union (`revert` / `unset` of a property that
//! has an api.json constructor) is a limitation: its payload offset is not
//! the payload's alignment.

use alloc::{
    format,
    string::{String, ToString},
    vec,
    vec::Vec,
};

use crate::codegen::{
    doc::{render, Doc},
    ir::{lower_first, snake_to_lower_camel, EnumShape, Expr, Item, Module, Prim},
    lang::{
        escape_quoted, item_comments, item_doc, simple_snake, unicode_braced, variant_ctor_method,
        ExprSyntax,
    },
    lower_types::union_tag,
    CodegenBackend, GeneratedFile,
};

/// The OCaml printer.
#[derive(Debug, Copy, Clone, Default)]
pub struct OCaml;

/// `(f a b)`; `(f ())` without arguments.
fn app(f: String, args: Vec<Doc>, broken: bool) -> Doc {
    if args.is_empty() {
        return Doc::text(format!("({f} ())"));
    }
    let mut items = vec![Doc::text(f)];
    items.extend(args);
    Doc::list("(", items, " ", ")", false, broken, false)
}

/// The ctypes type value of an api.json type: `az_color_u`.
fn ctype(ty: &str) -> String {
    simple_snake(&format!("Az{ty}"))
}

impl ExprSyntax for OCaml {
    fn int(&self, value: i128, ty: Prim) -> String {
        let neg = |s: String| if value < 0 { format!("({s})") } else { s };
        match ty {
            Prim::U8 => format!("(Unsigned.UInt8.of_int {value})"),
            Prim::U16 => format!("(Unsigned.UInt16.of_int {value})"),
            Prim::U32 => format!("(Unsigned.UInt32.of_int {value})"),
            Prim::U64 => format!("(Unsigned.UInt64.of_int {value})"),
            Prim::Usize => format!("(Unsigned.Size_t.of_int {value})"),
            Prim::I32 => neg(format!("{value}l")),
            Prim::I64 => neg(format!("{value}L")),
            Prim::Isize => format!("(Ctypes.Ptrdiff.of_int ({value}))"),
            Prim::I8 | Prim::I16 | Prim::F32 | Prim::F64 | Prim::Bool => neg(value.to_string()),
        }
    }

    fn float(&self, text: &str, _ty: Prim) -> String {
        match text {
            "nan" => "Float.nan".to_string(),
            "inf" => "Float.infinity".to_string(),
            "-inf" => "Float.neg_infinity".to_string(),
            t if t.starts_with('-') => format!("({t})"),
            t => t.to_string(),
        }
    }

    fn boolean(&self, b: bool) -> String {
        b.to_string()
    }

    fn string(&self, s: &str) -> Doc {
        Doc::text(format!(
            "(azul_az_string \"{}\")",
            escape_quoted(s, &[], &unicode_braced)
        ))
    }

    fn call(&self, class: &str, method: &str, args: Vec<Doc>, broken: bool) -> Doc {
        app(
            lower_first(&format!("Az{class}_{}", snake_to_lower_camel(method))),
            args,
            broken,
        )
    }

    fn variant(&self, ty: &str, shape: EnumShape, variant: &str, args: Vec<Doc>, broken: bool) -> Doc {
        match shape {
            EnumShape::CLike => Doc::text(format!("({ty}.to_int {ty}.{variant})")),
            EnumShape::Tagged => app(
                lower_first(&format!("Az{ty}_{}", variant_ctor_method(variant))),
                args,
                broken,
            ),
            EnumShape::Generic { arg, .. } => {
                let tag = union_tag(ty, variant).unwrap_or(0);
                let payload = match args.into_iter().next() {
                    Some(p) => app(
                        "Some".to_string(),
                        vec![app(format!("az_payload {}", ctype(arg)), vec![p], broken)],
                        broken,
                    ),
                    None => Doc::text("None"),
                };
                app(
                    format!("az_union {} {tag}", ctype(ty)),
                    vec![payload],
                    broken,
                )
            }
            // rejected by `limitation`
            EnumShape::TaggedShadowed => Doc::text("(failwith \"not expressible\")"),
        }
    }

    fn strukt(&self, ty: &str, fields: Vec<(String, Doc)>, broken: bool) -> Doc {
        let t = ctype(ty);
        let setters = fields
            .into_iter()
            .map(|(k, v)| {
                Doc::cat(vec![
                    Doc::text(format!("(fun v -> Ctypes.setf v {t}_field_{k} ")),
                    v,
                    Doc::text(")"),
                ])
            })
            .collect();
        app(
            format!("az_struct {t}"),
            vec![Doc::list("[", setters, "; ", "]", true, broken, false)],
            broken,
        )
    }

    fn vec(&self, ty: &str, elem: &str, items: Vec<Doc>, broken: bool) -> Doc {
        let f = lower_first(&format!("Az{ty}_copyFromPtr"));
        if items.is_empty() {
            return Doc::text(format!("({} ())", lower_first(&format!("Az{ty}_create"))));
        }
        let n = items.len();
        Doc::cat(vec![
            Doc::text(format!(
                "({f} (Ctypes.CArray.start (Ctypes.CArray.of_list {} ",
                ctype(elem)
            )),
            Doc::list("[", items, "; ", "]", false, broken, false),
            Doc::text(format!(")) (Unsigned.Size_t.of_int {n}))")),
        ])
    }

    fn unsupported(&self, _what: &str) -> Doc {
        Doc::text("(failwith \"not expressible\")")
    }

    fn limitation(&self, e: &Expr) -> Option<String> {
        match e {
            Expr::Variant {
                ty,
                shape: EnumShape::TaggedShadowed,
                variant,
                ..
            } => Some(format!(
                "{ty}.{variant} over its value alias: the OCaml bindings expose only the api.json \
                 constructor"
            )),
            _ => None,
        }
    }
}

const HELPERS: &str = r"(* A ctypes structure filled by setters. *)
let az_struct ty setters =
  let v = Ctypes.make ty in
  List.iter (fun set -> set v) setters;
  v

(* A CssPropertyValue alias (an opaque blob in the bindings): the u8 tag,
   then the payload at its own alignment. *)
let az_union ty tag payload =
  let v = Ctypes.make ty in
  let p = Ctypes.to_voidp (Ctypes.addr v) in
  Ctypes.(from_voidp uint8_t p <-@ Unsigned.UInt8.of_int tag);
  (match payload with None -> () | Some write -> write p);
  v

let az_payload t x p =
  Ctypes.(from_voidp t (to_voidp (from_voidp char p +@ alignment t)) <-@ x)
";

fn item_fn(item: &Item) -> String {
    let mut out = String::new();
    for line in &item_comments(&OCaml, item) {
        out.push_str(&format!("(* {} *)\n", line.replace("*)", "* )")));
    }
    let name = item.name.snake();
    match item_doc(&OCaml, item) {
        Ok(doc) => out.push_str(&format!(
            "let {name} () =\n  {}\n",
            render(&doc, "  ", 1)
        )),
        Err(reason) => out.push_str(&format!(
            "(* not expressible with the OCaml bindings: {} *)\n",
            reason.replace("*)", "* )")
        )),
    }
    out
}

impl CodegenBackend for OCaml {
    fn lang(&self) -> &'static str {
        "ocaml"
    }

    fn aliases(&self) -> &'static [&'static str] {
        &["ml"]
    }

    fn display_name(&self) -> &'static str {
        "OCaml"
    }

    fn extension(&self) -> &'static str {
        "ml"
    }

    fn emit_module(&self, m: &Module) -> String {
        let mut out = String::from(
            "(* Generated by azul-css codegen (OCaml). Do not edit by hand. *)\nopen Azul\n\n",
        );
        out.push_str(HELPERS);
        for item in &m.items {
            out.push('\n');
            out.push_str(&item_fn(item));
        }
        out
    }

    fn emit_project_files(&self, m: &Module) -> Vec<GeneratedFile> {
        let mut main = String::from("let () =\n");
        for (i, item) in m.items.iter().enumerate() {
            let name = item.name.snake();
            let sep = if i + 1 < m.items.len() { ";" } else { "" };
            main.push_str(&format!(
                "  ignore (Styles.{name} ());\n  print_endline \"{name}: built\"{sep}\n"
            ));
        }
        if m.items.is_empty() {
            main.push_str("  ()\n");
        }
        vec![
            GeneratedFile {
                path: "dune-project".to_string(),
                contents: "(lang dune 3.0)\n".to_string(),
            },
            GeneratedFile {
                path: "dune".to_string(),
                contents: "; Copy target/codegen/ocaml/ (library `azul`) to ./azul and libazul here,\n; \
                           then: dune exec ./main.exe\n(executable\n (name main)\n (modules main \
                           styles)\n (libraries ctypes ctypes-foreign azul))\n"
                    .to_string(),
            },
            GeneratedFile {
                path: "styles.ml".to_string(),
                contents: self.emit_module(m),
            },
            GeneratedFile {
                path: "main.ml".to_string(),
                contents: main,
            },
        ]
    }
}
